package com.neo.tracepilot;
import android.app.Activity;import android.os.Bundle;import android.webkit.*;import android.widget.*;import org.json.*;import java.util.*;
public final class MapActivity extends Activity{
 @Override public void onCreate(Bundle b){super.onCreate(b);long st=getIntent().getLongExtra("start",System.currentTimeMillis()-86400000L),en=getIntent().getLongExtra("end",System.currentTimeMillis()+1);String style=getIntent().getStringExtra("style");if(style==null)style="basic";TraceDb d=new TraceDb(this);List<TraceDb.Point> pts=d.points(st,en,5000);List<TraceDb.Gap> gs=d.gaps(st,en);d.close();if(!Net.internet(this)){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(Ui.dp(this,18),Ui.dp(this,28),Ui.dp(this,18),Ui.dp(this,18));root.setBackgroundColor(Ui.BG);root.addView(Ui.title(this,"Carte hors ligne"));root.addView(Ui.gap(this,8));root.addView(Ui.muted(this,"Le fond de carte nécessite Internet. Le suivi GPS, les capteurs, l'historique et les trajectoires restent 100 % locaux."));TraceView v=new TraceView(this);v.data(pts,gs);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,0,1f);lp.topMargin=Ui.dp(this,16);root.addView(v,lp);setContentView(root);return;}WebView w=new WebView(this);WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);w.setBackgroundColor(Ui.BG);w.loadDataWithBaseURL("https://tracepilot.local/",html(style,pts,gs),"text/html","UTF-8",null);setContentView(w);}
 String html(String style,List<TraceDb.Point> pts,List<TraceDb.Gap> gs){JSONArray raw=new JSONArray();for(TraceDb.Point p:pts){JSONArray q=new JSONArray();q.put(p.lat);q.put(p.lon);q.put(p.mode);raw.put(q);}JSONArray gaps=new JSONArray();for(TraceDb.Gap g:gs){if(!"reconstructed".equals(g.status)||g.pathJson==null||g.pathJson.length()<3)continue;try{JSONObject o=new JSONObject();o.put("mode",g.mode);o.put("path",new JSONArray(g.pathJson));gaps.put(o);}catch(Exception ignored){}}String tile="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",att="&copy; OpenStreetMap contributors",extra="";if("satellite".equals(style)||"hybrid".equals(style)){tile="https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}";att="Tiles &copy; Esri";if("hybrid".equals(style))extra="L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}',{maxZoom:19}).addTo(map);";}else if("relief".equals(style)){tile="https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png";att="OpenTopoMap / OpenStreetMap";}return "<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1,maximum-scale=1'><link rel='stylesheet' href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css'><style>html,body,#map{height:100%;margin:0;background:#05080d}</style></head><body><div id='map'></div><script src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js'></script><script>const raw="+raw+",gaps="+gaps+";const map=L.map('map');L.tileLayer('"+tile+"',{maxZoom:19,attribution:'"+att+"'}).addTo(map);"+extra+"const col={stationary:'#aab8c6',walk:'#57e294',run:'#ff9754',bike:'#ffc853',car:'#5b9bff',train:'#7d67ff',boat:'#4ed7ff',air:'#ff6876'};let bd=[];for(let i=1;i<raw.length;i++){let a=raw[i-1],b=raw[i];L.polyline([[a[0],a[1]],[b[0],b[1]]],{color:col[b[2]]||'#fff',weight:4,opacity:.9}).addTo(map);bd.push([b[0],b[1]]);}for(const g of gaps){L.polyline(g.path,{color:col[g.mode]||'#fff',weight:4,dashArray:'9 8'}).addTo(map);for(const p of g.path)bd.push(p);}if(bd.length)map.fitBounds(bd,{padding:[20,20]});else map.setView([43.3,5.4],4);</script></body></html>";}
}
